using System;using System.Drawing;using System.Windows.Forms;
namespace SlopStudio
{
 public sealed class AudioRegionEditor:UserControl
 {
  private NumericUpDown _offset,_length;private Label _name;private AudioWaveCanvas _canvas;private Track _track;private Region _region;private double _tempo;public event EventHandler<RegionTrimEventArgs> TrimRequested;public event EventHandler<PlayheadRequestEventArgs> PlayheadRequested;
  public AudioRegionEditor(){Dock=DockStyle.Fill;BackColor=Color.FromArgb(52,52,52);ForeColor=Color.Gainsboro;Font=new Font("Segoe UI",8);FlowLayoutPanel top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=30,WrapContents=false,BackColor=Color.FromArgb(64,64,64),Padding=new Padding(7,3,3,0)};_name=new Label{Width=155,Height=22,TextAlign=ContentAlignment.MiddleLeft};top.Controls.Add(_name);top.Controls.Add(new Label{Text="Source (s)",Width=62,Height=22,TextAlign=ContentAlignment.MiddleRight});_offset=new NumericUpDown{Minimum=0,Maximum=100000,DecimalPlaces=3,Increment=0.01m,Width=75,Height=22};top.Controls.Add(_offset);top.Controls.Add(new Label{Text="Length",Width=42,Height=22,TextAlign=ContentAlignment.MiddleRight});_length=new NumericUpDown{Minimum=0.25m,Maximum=1000000,DecimalPlaces=2,Increment=0.25m,Width=70};top.Controls.Add(_length);Button apply=new Button{Text="Apply Trim",Width=80,Height=23,FlatStyle=FlatStyle.Flat};apply.Click+=delegate{if(_track!=null&&_region!=null&&TrimRequested!=null)TrimRequested(this,new RegionTrimEventArgs{TrackId=_track.Id,RegionId=_region.Id,StartBeat=_region.StartBeat,LengthBeats=(double)_length.Value,SourceOffset=(double)_offset.Value});};top.Controls.Add(apply);_canvas=new AudioWaveCanvas{Dock=DockStyle.Fill};_canvas.PlayheadRequested+=delegate(object s,PlayheadRequestEventArgs e){if(PlayheadRequested!=null)PlayheadRequested(this,e);};Controls.Add(_canvas);Controls.Add(top);}
  public void SetContent(Track track,Region region,double tempo){_track=track;_region=region;_tempo=tempo;_name.Text=region==null?"Audio Editor":region.Name;_offset.Value=region==null?0:(decimal)region.AudioOffsetSeconds;_length.Value=region==null?0.25m:(decimal)region.LengthBeats;_canvas.SetContent(region,tempo);}
 }
 internal sealed class AudioWaveCanvas:ScaledCanvas
 {
  private Region _region;private double _tempo;public event EventHandler<PlayheadRequestEventArgs> PlayheadRequested;public AudioWaveCanvas(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);Font=new Font("Segoe UI",8);BackColor=Color.FromArgb(35,39,44);}
  public void SetContent(Region region,double tempo){_region=region;_tempo=tempo;Invalidate();}
  protected override void OnPaint(PaintEventArgs e){PreparePaint(e);base.OnPaint(e);e.Graphics.Clear(BackColor);if(_region==null)return;Rectangle body=new Rectangle(0,27,Width,Math.Max(1,Height-27));using(SolidBrush b=new SolidBrush(Color.FromArgb(37,85,107)))e.Graphics.FillRectangle(b,0,0,Width,22);for(int i=0;i<=8;i++){int x=i*Width/8;using(Pen p=new Pen(Color.FromArgb(59,65,72)))e.Graphics.DrawLine(p,x,23,x,Height);double beat=_region.StartBeat+i*_region.LengthBeats/8;StudioDraw.Label(e.Graphics,(beat/4+1).ToString("0.00"),Font,new Rectangle(x+4,1,70,20),Color.Gainsboro,TextFormatFlags.VerticalCenter);}WaveformCache.Draw(e.Graphics,body,_region.MediaPath,_region.AudioOffsetSeconds,_region.LengthBeats*60/_tempo,this,Color.FromArgb(121,189,222));}
  protected override void OnMouseDown(MouseEventArgs e){e=LogicalMouse(e);base.OnMouseDown(e);if(_region!=null&&PlayheadRequested!=null)PlayheadRequested(this,new PlayheadRequestEventArgs(_region.StartBeat+e.X/(double)Math.Max(1,Width)*_region.LengthBeats));}
 }
}
